head.script:
scwin.setSimulate = function() {
    //today = new Date();
    //todayDate = today.getFullYear() + '-' + (today.getMonth() + 1) + '-' + today.getDate();
	todayDate = WebSquare.date.getCurrentServerDate("yyyy-MM-dd");
    return WebSquare.wUnit.getDomById('inputCalendar1_calendar_currentDate').innerText == todayDate;
}
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "1500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('inputCalendar1_img').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "scwin.setSimulate()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.unitTest();

scwin.onpageload = function() {
    window.today;
	window.todayDate;
}
